import { CFG } from './config.js';
import { mulberry32, angDiff } from './util.js';

/**
 * The fillet of a corner of deflection phi reaches r*tan(phi/2) back from the
 * vertex. If two neighbouring fillets reach further than the straight between
 * them, the road doubles back on itself and the game is unplayable. Fail loudly
 * rather than shipping a broken road.
 */
function assertStraight(len, vertex) {
  if (!(len >= CFG.minStraight)) {
    throw new Error(
      `track geometry broken at vertex ${vertex}: straight is ${len.toFixed(1)}px, ` +
      `needs >= ${CFG.minStraight}. Raise segLen, or lower driftRadius.`
    );
  }
}

// `project` tie-break. `PROJECT_BRANCH` is the index gap that means "a different
// branch of the road" (well beyond the few samples between neighbouring points);
// `PROJECT_TIE` is how close in space two branches must be to count as crossing.
// Both are generous next to the real numbers: samples sit 5-12px apart, and a
// self-crossing puts two branches within a pixel.
const PROJECT_BRANCH = 40;
const PROJECT_TIE = 0.05;

/**
 * The road.
 *
 * The centreline is straights joined by circular arcs of radius driftRadius, one
 * arc per corner. The pole you sling around is the centre of that arc, so when
 * you latch on the car follows the road exactly. That is the whole trick: the
 * mechanic and the road are the same shape.
 *
 * The default builder makes every corner a quarter turn, alternating left/right,
 * so the road is a staircase. One corner means one pole means one sling - there
 * is never a second pole within reach on a turn - and alternating keeps the road
 * from folding back on itself. A track may instead supply an explicit op list
 * (see `buildOps`) for corners that are not quarter turns: hairpins (180) and
 * loops (270) among them.
 *
 * Vertices are appended lazily, one at a time, and a corner is only built once
 * the next vertex exists (a corner needs both directions). One builder, used for
 * the opening stretch and for growth, so the two can never disagree.
 */
export class Track {
  constructor(seed = 1, opts = {}) {
    this.seed = seed;
    this.rng = mulberry32(seed);
    // A finite track (speedrun) builds an exact number of corners and then a
    // closing straight with a finish line. An endless track keeps growing.
    this.finite = Number.isInteger(opts.corners) && opts.corners > 0;
    this.cornerLimit = this.finite ? opts.corners : Infinity;
    this.finishLen = opts.finishLen ?? CFG.speedrunFinish;
    // A finite track can be given its own rhythm: `segLens` is the vertex-to-
    // vertex distance for each straight, and `leadIn` the opening one. Endless
    // play leaves both out and gets the uniform CFG lengths.
    this.segLens = Array.isArray(opts.segLens) ? opts.segLens : null;
    this.leadIn = opts.leadIn ?? CFG.leadIn;
    this.radius = opts.radius ?? CFG.driftRadius;
    this.targetTime = Number.isFinite(opts.targetTime) ? opts.targetTime : null;
    this.segIndex = 0;
    this.finishS = Infinity;
    this.finish = null;
    this.v = [{ x: 0, y: 0 }];
    this.dir = [];
    this.heading = CFG.baseHeading;
    // Alternate the turn direction, but pick which way the first corner goes
    // from the seed so different roads are not all mirror images of each other.
    this.turnSign = this.rng() < 0.5 ? -1 : 1;
    this.fillets = [];
    this.feats = [];
    this.road = [];
    this.rs = [];
    this.length = 0;
    this.cur = this.v[0];
    // A track can instead be given an explicit op list: straights and signed
    // arcs, walked in order. That is what the hairpin and loop tracks (21-25)
    // need, because their corners are not quarter turns and the staircase
    // builder above only ever emits a fixed 90 degrees. The two builders share
    // every primitive below, so a road built either way is the same kind of
    // object.
    this.ops = Array.isArray(opts.ops) ? opts.ops : null;
    if (this.ops) {
      this.buildOps();
    } else {
      this.ensure(this.finite ? this.cornerLimit : 240);
      if (this.finite) this.buildFinish();
    }
  }

  /**
   * Build a road from an explicit op list: `{t:'L', len}` for a straight and
   * `{t:'A', deg}` for a signed arc (positive is left of the current heading).
   * The opening straight is `leadIn`, and the closing straight is sized to hit
   * `targetTime` exactly as `buildFinish` does for a staircase track.
   */
  buildOps() {
    let b = { x: this.cur.x + Math.cos(this.heading) * this.leadIn, y: this.cur.y + Math.sin(this.heading) * this.leadIn };
    this.pushLine(this.cur, b, this.leadIn);
    this.cur = b;
    for (const op of this.ops) {
      if (op.t === 'A') {
        const th = (op.deg * Math.PI) / 180;
        const s = Math.sign(th) || 1;
        // A corner may carry its own radius. A run of corners that all turn the
        // same way and widen as they go is a spiral: it winds round without the
        // road crossing back over itself, which a single arc of more than a half
        // turn cannot do (its exit tangent always recrosses its entry).
        const r = op.r ?? this.radius;
        // The centre sits one radius to the side of the current heading, so the
        // arc starts tangent to the road. This has to be recomputed per corner:
        // the heading has turned by the previous corner, and a stale perpendicular
        // would kink the road at every join.
        const nl = { x: Math.cos(this.heading + Math.PI / 2), y: Math.sin(this.heading + Math.PI / 2) };
        const c = { x: this.cur.x + s * nl.x * r, y: this.cur.y + s * nl.y * r };
        const a1 = Math.atan2(this.cur.y - c.y, this.cur.x - c.x);
        const a2 = a1 + th;
        const fil = {
          k: this.fillets.length, c, r, sign: s, a1, a2, phi: th,
          t1: this.cur, t2: { x: c.x + Math.cos(a2) * r, y: c.y + Math.sin(a2) * r },
          s0: this.length, s1: this.length + r * Math.abs(th),
        };
        this.fillets.push(fil);
        this.pushArc(fil);
        this.cur = fil.t2;
        this.heading += th;
      } else {
        const len = op.len;
        if (len > 0.01) {
          // The staircase's min-straight rule keeps neighbouring fillets from
          // overlapping on a road that alternates 90s. An op track is authored by
          // hand and may deliberately tuck corners closer (a hairpin's connector),
          // so it is allowed to be shorter - but never negative.
          b = { x: this.cur.x + Math.cos(this.heading) * len, y: this.cur.y + Math.sin(this.heading) * len };
          this.pushLine(this.cur, b, len);
          this.cur = b;
        }
      }
    }
    // Nothing to grow: the road is complete. `extendAhead` sees the limit.
    this.cornerLimit = this.fillets.length;
    this.buildFinish(this.heading);
  }

  /**
   * Close a finite track: run a straight on from the last corner's exit and
   * put the finish line at its end. `finishS` is the road position the car has
   * to reach to stop the clock.
   */
  buildFinish(headingOverride) {
    const last = this.fillets[this.fillets.length - 1];
    const a2 = last.a2;
    const heading = headingOverride ?? Math.atan2(last.sign * Math.cos(a2), last.sign * -Math.sin(a2));
    const a = { x: this.cur.x, y: this.cur.y };
    // If the track asked for a target time, size the closing straight so the
    // clock lands on it. The car starts `speedrunStartFrac` into the lead-in, so
    // the run is the road left after the start divided by speed. This is exact -
    // a clean line drives the centreline, and the road's own length is known -
    // which is why the twenty tracks can each be pinned to their target.
    let len = this.finishLen;
    if (this.targetTime !== null) {
      const startS = CFG.speedrunStartFrac * this.leadIn;
      const want = this.targetTime * CFG.speed + startS - this.length;
      if (want > 120) len = want;
    }
    const b = { x: a.x + Math.cos(heading) * len, y: a.y + Math.sin(heading) * len };
    this.pushLine(a, b, len);
    this.cur = b;
    this.finishS = this.length;
    this.finish = { a, b, heading };
  }

  /** Advance the heading one corner: always a quarter turn, direction alternating. */
  stepHeading() {
    this.heading += this.turnSign * CFG.turn;
    this.turnSign = -this.turnSign;
  }

  addVertex() {
    const lastV = this.v[this.v.length - 1];
    this.stepHeading();
    let len = this.v.length === 1 ? this.leadIn : CFG.segLen;
    // A per-track rhythm overrides the uniform spacing. `segLens` cycles, so a
    // short list gives a repeating pulse and a long one an irregular one.
    if (this.segLens && this.segLens.length) {
      if (this.v.length > 1) len = this.segLens[this.segIndex++ % this.segLens.length];
    }
    const nv = {
      x: lastV.x + Math.cos(this.heading) * len,
      y: lastV.y + Math.sin(this.heading) * len,
    };
    this.dir.push(this.heading);
    this.v.push(nv);
    // A corner needs both an incoming and an outgoing direction, so the very
    // first vertex (which has no incoming direction) is never a corner.
    if (this.v.length >= 3) this.finalizeCorner(this.v.length - 2);
  }

  /** Build the corner at vertex k. Needs dir[k-1] and dir[k], so v[k+1] too. */
  finalizeCorner(k) {
    const r = this.radius;
    const dIn = this.dir[k - 1], dOut = this.dir[k];
    const phi = angDiff(dIn, dOut);
    const L = r * Math.tan(Math.abs(phi) / 2);
    const vk = this.v[k];
    const t1 = { x: vk.x - Math.cos(dIn) * L, y: vk.y - Math.sin(dIn) * L };
    const t2 = { x: vk.x + Math.cos(dOut) * L, y: vk.y + Math.sin(dOut) * L };
    const sign = Math.sign(phi) || 1;
    const nl = { x: -Math.sin(dIn), y: Math.cos(dIn) };
    const c = { x: t1.x + sign * nl.x * r, y: t1.y + sign * nl.y * r };

    const straightLen = Math.hypot(t1.x - this.cur.x, t1.y - this.cur.y);
    assertStraight(straightLen, k);
    this.pushLine(this.cur, t1, straightLen);

    const a1 = Math.atan2(t1.y - c.y, t1.x - c.x);
    const a2 = a1 + sign * Math.abs(phi);
    const fil = { k, c, r, sign, a1, a2, phi, t1, t2, s0: this.length, s1: this.length + r * Math.abs(phi) };
    this.fillets.push(fil);
    this.pushArc(fil);
    this.cur = t2;
  }

  pushLine(a, b, len) {
    this.feats.push({ type: 'line', a, b, len, s0: this.length, s1: this.length + len });
    // Sample straights as finely as arcs. The renderer walks this polyline, so a
    // straight stored as two points would be one long quad that cannot reach the
    // bottom of the screen: the ribbon would stop short and leave bare grass
    // under the camera.
    const n = Math.max(1, Math.ceil(len / 12));
    for (let k = 0; k <= n; k++) {
      const t = k / n;
      this.road.push({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t });
      this.rs.push(this.length + len * t);
    }
    this.length += len;
  }

  pushArc(f) {
    const len = f.s1 - f.s0;
    this.feats.push({ type: 'arc', c: f.c, r: f.r, a1: f.a1, a2: f.a2, sign: f.sign, len, fil: f, s0: f.s0, s1: f.s1 });
    const n = Math.max(2, Math.ceil(len / 5));
    for (let k = 0; k <= n; k++) {
      const a = f.a1 + (f.a2 - f.a1) * (k / n);
      this.road.push({ x: f.c.x + Math.cos(a) * f.r, y: f.c.y + Math.sin(a) * f.r });
      this.rs.push(f.s0 + len * (k / n));
    }
    this.length = f.s1;
  }

  /** Make sure at least n corners exist, without overrunning a finite track. */
  ensure(n) {
    const target = Math.min(n, this.cornerLimit);
    while (this.fillets.length < target) this.addVertex();
  }

  /** Keep plenty of road built ahead of the car. */
  extendAhead(roadIndex) {
    while (this.road.length - roadIndex < 400) {
      const next = Math.min(this.fillets.length + 4, this.cornerLimit);
      if (next === this.fillets.length) break;
      this.ensure(next);
    }
  }

  /**
   * Nearest point on the centreline to (x, y). `hint` is the road index we were
   * near last frame, so this stays cheap on a very long road.
   */
  project(x, y, hint = 0) {
    const lo = Math.max(0, hint - 60);
    const hi = Math.min(this.road.length - 1, hint + 140);
    let best = null;
    for (let i = lo; i < hi; i++) {
      const a = this.road[i], b = this.road[i + 1];
      const dx = b.x - a.x, dy = b.y - a.y;
      const L = dx * dx + dy * dy;
      let t = L ? ((x - a.x) * dx + (y - a.y) * dy) / L : 0;
      t = t < 0 ? 0 : t > 1 ? 1 : t;
      const px = a.x + t * dx, py = a.y + t * dy;
      const d = Math.hypot(x - px, y - py);
      const cand = { d, s: this.rs[i] + (this.rs[i + 1] - this.rs[i]) * t, i, x: px, y: py };
      if (!best) { best = cand; continue; }
      // A tie only matters when the two samples are on *different branches* of the
      // road (far apart in index) yet equally close in space. On an ordinary road
      // the nearest sample is unique, and adjacent samples 5-12px apart are never
      // within a hundredth of each other, so this never fires and the behaviour is
      // exactly the old "first strictly-nearest wins". But a 270-degree corner
      // doubles back over its own entry, and at that crossing two branches are the
      // same point in space: both are correct, and the only sensible choice is to
      // stay on the branch we were already following. Without it the road position
      // hops to the far branch and jumps backwards.
      if (Math.abs(cand.i - best.i) > PROJECT_BRANCH && Math.abs(cand.d - best.d) < PROJECT_TIE) {
        if (Math.abs(cand.i - hint) < Math.abs(best.i - hint)) best = cand;
      } else if (cand.d < best.d) {
        best = cand;
      }
    }
    return best;
  }

  /** The first corner whose arc has not finished by road position s. */
  filletAt(s) {
    for (let k = 0; k < this.fillets.length; k++) {
      if (this.fillets[k].s1 > s) return k;
    }
    return this.fillets.length - 1;
  }

  /** Centreline point and heading at road position s. */
  pointAt(s) {
    const rs = this.rs;
    let lo = 0, hi = rs.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (rs[mid] < s) lo = mid + 1; else hi = mid;
    }
    const i = Math.max(0, Math.min(rs.length - 2, lo - 1));
    const a = this.road[i], b = this.road[i + 1];
    const span = rs[i + 1] - rs[i] || 1;
    const t = Math.max(0, Math.min(1, (s - rs[i]) / span));
    return {
      x: a.x + (b.x - a.x) * t,
      y: a.y + (b.y - a.y) * t,
      heading: Math.atan2(b.y - a.y, b.x - a.x),
    };
  }
}
